@startuml

class School {
  + name : string
}

class Person {
  + firstName : string
  + lastName : string
}

class Teacher extends Person {
  + email : string
}

class Student extends Person {}

class TeachingAssignment {
  + hours : int
}

class Room {
  + name : string
}

class Classroom extends Room {
  + capacity : int
}

class Gym extends Room {
  + size : float
}

class ClassGroup {
  + name : string
}

School "1" -- "1" Teacher : principal
School "1" -- "1..*" Teacher : employs
School "1" -- "0..*" TeachingAssignment
Teacher "1" -- "0..3" TeachingAssignment

Student "1" -- "1" ClassGroup
ClassGroup "1" -- "1" Classroom
ClassGroup "1" -- "10..31" Student

@enduml

